<?php
namespace App\Actions\Inventory;use App\Models\{InventoryMovement,Product,User};use DomainException;use Illuminate\Support\Facades\DB;
class AdjustProductStock{public function execute(Product $product,float $change,string $type,?string $note=null,?User $by=null):InventoryMovement{if($change==0.0)throw new DomainException('Số lượng điều chỉnh phải khác 0.');return DB::transaction(function()use($product,$change,$type,$note,$by){$locked=Product::withTrashed()->lockForUpdate()->findOrFail($product->id);$available=(float)$locked->stock_quantity;$balance=$available+$change;if($balance<0){$requested=abs($change);throw new DomainException("Không đủ tồn kho. Muốn xuất {$requested} {$locked->unit}, hiện chỉ còn {$available} {$locked->unit}.");}$locked->update(['stock_quantity'=>$balance]);return InventoryMovement::create(['product_id'=>$locked->id,'type'=>$type,'quantity_change'=>$change,'balance_after'=>$balance,'created_by'=>$by?$by->id:null,'note'=>$note]);});}}
